// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool, IStolenNftOracle} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    MockNFT nft;

    // c's immutable `factory` points here; sellQuote reads protocolFeeRate()
    uint16 public protocolFeeRate;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
        nft = new MockNFT();
        protocolFeeRate = 0;
    }

    function testFuzz_property(uint128 vBase, uint128 vNft, address seller, uint256 tokenId) public {
        // Admissible domain: NFT side must exceed a single 1e18 weight so the
        // trade is valid, and base reserves must be large enough that the
        // payout is strictly positive.
        vNft = uint128(bound(uint256(vNft), 2e18, 1e24));
        vBase = uint128(bound(uint256(vBase), uint256(vNft) + 1e18, type(uint128).max));
        vm.assume(seller != address(0) && seller != address(c));

        c.initialize(address(0), address(nft), vBase, vNft, 0, 0, bytes32(0), false, false);

        // Fund the pool so the ETH payout succeeds.
        vm.deal(address(c), uint256(vBase) + 1 ether);

        uint256 reservesBefore = c.virtualBaseTokenReserves();

        uint256[] memory ids = new uint256[](1);
        ids[0] = tokenId;
        uint256[] memory weights = new uint256[](1);
        weights[0] = 1e18; // merkleRoot is zero, so any weight of 1e18 is admissible

        PrivatePool.MerkleMultiProof memory proof;
        IStolenNftOracle.Message[] memory stolenProofs = new IStolenNftOracle.Message[](0);

        vm.prank(seller);
        c.sell(ids, weights, proof, stolenProofs);

        uint256 reservesAfter = c.virtualBaseTokenReserves();

        // General rule: a completed sell strictly shrinks the pool's virtual
        // base token reserves (it pays out base tokens).
        assertTrue(reservesAfter < reservesBefore, "virtual base reserves must decrease after sell");
    }

    receive() external payable {}
}

contract MockNFT {
    function safeTransferFrom(address, address to, uint256) external {
        if (to.code.length > 0) {
            (bool ok, bytes memory ret) = to.call(
                abi.encodeWithSignature(
                    "onERC721Received(address,address,uint256,bytes)",
                    msg.sender, msg.sender, 0, ""
                )
            );
            require(ok && abi.decode(ret, (bytes4)) == bytes4(0x150b7a02), "UNSAFE_RECIPIENT");
        }
    }

    function ownerOf(uint256) external pure returns (address) {
        return address(0xdead);
    }

    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }
}
